"""Exact bounded quadratic quadrature illustration, not a generic integrator."""
from fractions import Fraction


def trapezoid_square(a, b, panels):
    if any(type(x) not in (int, Fraction) or abs(x) > 1000 for x in (a, b)):
        raise ValueError("expected bounded exact int/Fraction endpoints")
    if a > b:
        raise ValueError("expected ordered endpoints")
    if type(panels) is not int or not 1 <= panels <= 1000:
        raise ValueError("expected1..1000panels, excluding bool")
    a, b = Fraction(a), Fraction(b)
    width = (b-a)/panels
    value = width*((a*a+b*b)/2 + sum((a+j*width)**2 for j in range(1, panels)))
    # For f=x^2, M2=2 and exact evaluation give a proved absolute error bound.
    absolute_error_bound = (b-a)*width*width/6
    return value, absolute_error_bound


if __name__ == "__main__":
    for n in (1, 2, 4):
        value, bound = trapezoid_square(0, 1, n)
        print(n, str(value), str(bound), value-Fraction(1, 3) == bound)
